const tareaInput=document.getElementById("tareaInput"),agregarBtn=document.getElementById("agregarBtn"),listaTareas=document.getElementById("listaTareas");function agregarTarea(){let e=tareaInput.value.trim();if(""===e){alert("Escribe una tarea antes de agregarla.");return}let a=document.createElement("li");a.classList.add("tarea");let t=document.createElement("span");t.textContent=e,t.addEventListener("click",function(){t.classList.toggle("completada")});let n=document.createElement("button");n.textContent="Eliminar",n.classList.add("eliminar"),n.addEventListener("click",function(){a.remove()}),a.appendChild(t),a.appendChild(n),listaTareas.appendChild(a),tareaInput.value="",tareaInput.focus()}agregarBtn.addEventListener("click",agregarTarea),tareaInput.addEventListener("keypress",function(e){"Enter"===e.key&&agregarTarea()});